class MemoryBlock:
    def __init__(self, size):
        self.size = size
        self.data = [0] * size  # Initialize memory block with zeros
        self.is_allocated = False  # Track if the block is allocated
        self.pointer = 0  # Pointer to the start of the block

    def allocate(self):
        if not self.is_allocated:
            self.is_allocated = True
            return self.pointer
        else:
            raise RuntimeError("Memory block is already allocated")

    def deallocate(self):
        if self.is_allocated:
            self.is_allocated = False
            self.data = [0] * self.size  # Reset memory to zeros
            print(f"Memory block of size {self.size} deallocated.")
        else:
            print("Memory block is not allocated.")

    def get_status(self):
        return {
            'size': self.size,
            'allocated': self.is_allocated,
            'data': self.data
        }

# Example usage:
if __name__ == "__main__":
    # Create a memory block of size 10
    block = MemoryBlock(10)

    # Allocate memory
    ptr = block.allocate()
    print(f"Memory allocated at pointer: {ptr}")

    # Show current status
    status = block.get_status()
    print(f"Current memory status: {status}")

    # Deallocate memory
    block.deallocate()

    # Show updated status
    status = block.get_status()
    print(f"Updated memory status: {status}")

